type LogoLoopProps = { reducedMotion: boolean };

const wordmarks = ['React', 'Next.js', 'TypeScript', 'Node.js', 'AWS', 'PostgreSQL', 'Vitest'];

/** React Bits-style wordmark loop for the services section. */
export function LogoLoop({ reducedMotion }: LogoLoopProps) {
  return <div className={`logo-loop${reducedMotion ? ' logo-loop-static' : ''}`} aria-label={`Technology stack: ${wordmarks.join(', ')}`}><div className="logo-loop-track">{[0, 1].map((copy) => <div className="logo-loop-group" key={copy} aria-hidden={copy === 1}>{wordmarks.map((wordmark) => <span key={wordmark}>{wordmark}</span>)}</div>)}</div></div>;
}
