'use client';

import { useRef } from 'react';

type DarkVeilProps = { reducedMotion: boolean };

/** A lightweight, theme-aware adaptation of React Bits' Dark Veil background. */
export function DarkVeil({ reducedMotion }: DarkVeilProps) {
  const veilRef = useRef<HTMLDivElement>(null);
  const handlePointerMove: React.PointerEventHandler<HTMLDivElement> = (event) => {
    if (reducedMotion || event.pointerType !== 'mouse' || !veilRef.current) return;
    const bounds = veilRef.current.getBoundingClientRect();
    veilRef.current.style.setProperty('--veil-x', `${((event.clientX - bounds.left) / bounds.width) * 100}%`);
    veilRef.current.style.setProperty('--veil-y', `${((event.clientY - bounds.top) / bounds.height) * 100}%`);
  };
  return <div ref={veilRef} className={`dark-veil${reducedMotion ? ' dark-veil-static' : ''}`} onPointerMove={handlePointerMove} aria-hidden="true" />;
}
